import os, csv
from pathlib import Path
from decimal import Decimal

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190205", "20190206", "20190207"]
segs = {("靖边站", "石家庄站"), ("霍尔果斯首站", "乌鲁木齐站")}
lines = {"冀宁线", "西气东输二线"}

tot = {l: Decimal("0") for l in lines}
detail = []
for d in dates:
    with open(DIR / f"{d}_pipeline.csv", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            key = (row["起点站名"], row["终点站名"])
            if key in segs and row["管道划分"] in lines:
                v = abs(Decimal(row["管道流量"]))
                tot[row["管道划分"]] += v
                detail.append((d, row["管道划分"], key[0] + "->" + key[1], str(v)))

for r in detail:
    print(r)
for l in lines:
    print(l, "累计:", tot[l])
print("差值:", abs(tot["冀宁线"] - tot["西气东输二线"]))

