import os
import csv
import json
from pathlib import Path
from decimal import Decimal

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190202", "20190203", "20190204", "20190205", "20190206"]
targets = ["中俄东线", "陕京二线"]

result = {}
for d in dates:
    csv_path = DIR / f"{d}_pipeline.csv"
    sums = {t: Decimal("0") for t in targets}
    counts = {t: 0 for t in targets}
    with open(csv_path, encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            name = row["管道划分"].strip()
            if name in targets:
                sums[name] += abs(Decimal(row["管道流量"].strip()))
                counts[name] += 1
    result[d] = {
        t: {"abs_flow_sum": str(sums[t]), "segment_count": counts[t]}
        for t in targets
    }

# window totals
totals = {t: sum(Decimal(result[d][t]["abs_flow_sum"]) for d in dates) for t in targets}
diff = abs(totals["中俄东线"] - totals["陕京二线"])
higher = "中俄东线" if totals["中俄东线"] > totals["陕京二线"] else "陕京二线"

payload = {
    "window": dates,
    "daily": result,
    "window_totals": {t: str(totals[t]) for t in targets},
    "higher": higher,
    "difference": str(diff),
}
print(json.dumps(payload, ensure_ascii=False, indent=2))

