    top5 = sorted(seg_zero.items(), key=lambda kv: (-kv[1], kv[0]))[:5]
    result[p] = {
        "segment_days": total,
        "zero_days": len(zero_rows),
        "zero_ratio": len(zero_rows) / total if total else None,
        "top5_zero_segments": top5,
        "distinct_segments": len({r["seg"] for r in p_rows}),
    }

