]

daily_totals = {}
daily_users = {}

for fname in files:
    fpath = CONSUMER_DIR / fname
    date_str = fname.replace("_consumer.csv", "")

    shanghai_consumption = {}  # user -> consumption sum
    with open(fpath, "r", encoding="utf-8") as f:
        header = f.readline().strip()
        for line in f:
            parts = line.strip().split(",")
            if len(parts) < 5:
                continue
            pipeline, region, supply_point, user, consumption = parts[0], parts[1], parts[2], parts[3], parts[4]
            if region == "上海":
                try:
                    val = float(consumption)
                except ValueError:
                    continue
                if user in shanghai_consumption:
                    shanghai_consumption[user] += val
                else:
                    shanghai_consumption[user] = val

    daily_totals[date_str] = sum(shanghai_consumption.values())
    daily_users[date_str] = shanghai_consumption

    print(f"\n=== {date_str} ===")
    for u, v in sorted(shanghai_consumption.items(), key=lambda x: -x[1]):
        print(f"  {u}: {v}")
    print(f"  Total: {daily_totals[date_str]}")

# Cross-day user aggregation
all_user_totals = {}
for date_str, users in daily_users.items():
    for u, v in users.items():
        if u in all_user_totals:
            all_user_totals[u] += v
        else:
            all_user_totals[u] = v

print("\n=== Cross-day user totals (all 5 days) ===")
for u, v in sorted(all_user_totals.items(), key=lambda x: -x[1]):
    print(f"  {u}: {v}")

avg_daily = sum(daily_totals.values()) / len(daily_totals)
peak_day = max(daily_totals, key=daily_totals.get)

print(f"\n=== Summary ===")
print(f"Daily totals: {daily_totals}")
print(f"Average daily total: {avg_daily:.3f}")
print(f"Peak day: {peak_day} with total {daily_totals[peak_day]:.3f}")
print(f"Top user on peak day: {max(daily_users[peak_day].items(), key=lambda x: x[1])}")
print(f"Top user overall (cross-day): {max(all_user_totals.items(), key=lambda x: x[1])}")

